parameters.jsCode:
const calc = $('Calculate Quote Details').first()?.json || {};
if (!calc.success) return [{ json: { success: false, error: true, message: calc.error } }];
const created = $('Create Quote Record').first()?.json || {};
const delivery = $('Generate & Send PDF').first()?.json || {};
const deliveryError = delivery.error?.message || delivery.error || delivery.message || null;
let message;
if (calc.requires_review) {
  message = `I've recorded your request for ${calc.product_name}. A representative must confirm pricing before we can send a quote.`;
} else if (delivery.success) {
  message = `Quote ${created.quote_number} for ${calc.product_name} has been sent as a PDF. Total: ${created.currency} ${Number(created.total).toLocaleString('en-US', {minimumFractionDigits: 2})}. Valid until ${created.valid_until}.`;
} else {
  message = `Quote ${created.quote_number} for ${calc.product_name} was created, but I couldn't send its PDF automatically. The team will follow up. ` + (deliveryError ? `(${String(deliveryError).slice(0, 180)})` : '');
}
return [{ json: { success: true, message, quote: {
  quote_number: created.quote_number, quote_id: created.id, product: calc.product_name,
  quantity: calc.quantity, unit_price: calc.unit_price, subtotal: calc.subtotal,
  total: created.total, currency: created.currency, valid_until: created.valid_until,
  requires_review: calc.requires_review, pdf_sent: !!delivery.success,
  pdf_error: deliveryError, metadata: calc.metadata
} } }];
